fun ongkir(beratGram: Int, kota: String): Int {
    val dasar = if (kota == "Jakarta") 9_000 else 15_000
    val tambahanKg = if (beratGram > 1000) (beratGram - 1) / 1000 else 0
    return dasar + tambahanKg * 4_000
}

fun main() {
    println(ongkir(800, "Jakarta"))
    println(ongkir(2500, "Jakarta"))
    println(ongkir(2500, "Makassar"))
}

