        return "1 IDR = \(n) USD"
    } catch {
        return "Gagal: \(error.localizedDescription)"
    }
}

class Konverter(private val perRupiah: Map<String, Double>) {   // 1 IDR = ... mata uang lain
    fun dariRupiah(rupiah: Long, kode: String): Double {
        val kurs = perRupiah[kode] ?: error("Kurs $kode belum ada")
        return rupiah * kurs
    }

    fun keRupiah(nilai: Double, kode: String): Long {
        val kurs = perRupiah[kode] ?: error("Kurs $kode belum ada")
        return Math.round(nilai / kurs)
    }
}

fun main() {
    val k = Konverter(mapOf("USD" to 0.0000625, "SGD" to 0.0000842, "MYR" to 0.000294))
    println("Rp1.000.000 = ${"%.2f".format(k.dariRupiah(1_000_000, "USD"))} USD")
    println("Rp1.000.000 = ${"%.2f".format(k.dariRupiah(1_000_000, "MYR"))} MYR")
    println("50 SGD = Rp${k.keRupiah(50.0, "SGD")}")
    println(runCatching { k.dariRupiah(10_000, "JPY") }.exceptionOrNull()?.message)
}

class KursRepository(private val api: KursApi, private val db: AppDb) {
    private val q = db.kursQueries

    val semua: Flow<List<Kurs>> = q.semua().asFlow().mapToList(Dispatchers.Default)

    suspend fun segarkan() {
        val respons = api.kurs("IDR")
        val waktu = Clock.System.now().epochSeconds
        db.transaction {
            respons.rates.forEach { (kode, nilai) -> q.simpan(kode, nilai, waktu) }
        }
    }
}

